//! M3 acceptance tests (PLAN-APPLICATION): import fidelity,
//! export/import round-trip, and the faceted marker in file metadata.
//!
//! The exact-B-rep fixture (a box with a cylindrical through hole) is
//! generated by `fixtures::box_with_hole_step` — the entity graph is
//! hand-authored per AP203 and committed under `tests/fixtures/` by the
//! fixture test below (regenerable, never hand-edited).

use std::path::PathBuf;
use std::process::Command;

mod fixtures;

/// Box 30×20×10 mm with a radius-4 through hole: the exact volume.
const EXACT_VOLUME: f64 = 30.0 * 20.0 * 10.0 - std::f64::consts::PI * 4.0 * 4.0 * 10.0;

fn fixture_path() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/box-with-hole.step")
}

/// Build the committed fixture when missing (the regeneration path).
fn ensure_fixture() {
    if !fixture_path().exists() {
        std::fs::create_dir_all(fixture_path().parent().unwrap()).unwrap();
        std::fs::write(fixture_path(), fixtures::box_with_hole_step()).unwrap();
    }
}

/// Parse the first `volume <mm³>` number out of a `stats` run.
fn volume_of(stats: &str) -> f64 {
    stats
        .lines()
        .find(|l| l.contains("volume"))
        .and_then(|l| l.split("volume ").nth(1))
        .and_then(|rest| rest.split_whitespace().next())
        .unwrap()
        .parse()
        .unwrap()
}

#[test]
fn fixture_imports_within_deflection_derived_tolerance() {
    ensure_fixture();
    let deflection = 0.5; // mm
    let text = std::fs::read_to_string(fixture_path()).unwrap();
    let set = fc_step::parse::EntitySet::parse(&text).unwrap();
    let solids = fc_step::import::import_solids(&set, deflection).unwrap();
    assert_eq!(solids.len(), 1, "one solid in the fixture");
    let mesh = &solids[0].1;

    // Tolerance derivation: the hole is the only curved surface, so the
    // volume error is bounded by the sagitta deficit of the inscribed
    // polygon: the area gap between the circle and the n-gon,
    //   πr² − (n/2) r² sin(2π/n) = (π r²/2)·(2π/n)²/6 + O(n⁻⁴),
    // times the hole height. Chord ≤ deflection means
    //   step = 2π/n ≤ 2·acos(1 − d/r), so the bound is
    //   (π r²/12)·step²·h.
    let (r, h) = (4.0_f64, 10.0_f64);
    let step = 2.0 * (1.0 - deflection / r).acos();
    let bound = std::f64::consts::PI * r * r / 12.0 * step * step * h;
    let volume = mesh.volume();
    let err = (volume - EXACT_VOLUME).abs();
    assert!(
        err <= bound * 1.5, // 1.5× engineering margin over the analytic bound
        "volume {volume} vs exact {EXACT_VOLUME}: err {err} > derived bound {bound}"
    );
    assert!(
        volume > EXACT_VOLUME,
        "an inscribed hole polygon removes less material, so the volume must sit \
         above exact (volume {volume} <= exact {EXACT_VOLUME})"
    );
}

#[test]
fn partdesign_pad_exports_reimports_within_tolerance() {
    // Build a Pad over a ring (washer) profile — curved surfaces on
    // both walls — via the real CLI, then round-trip it through STEP.
    let dir = std::env::temp_dir().join(format!("fc-step-e2e-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let doc = dir.join("pad.fcstd");
    let step_out = dir.join("pad.step");
    let doc2 = dir.join("roundtrip.fcstd");

    let cli = cli_path();
    let run = |args: &[&str]| {
        let out = Command::new(&cli).args(args).output().unwrap();
        assert!(
            out.status.success(),
            "freecad-rs {:?} failed: {}",
            args,
            String::from_utf8_lossy(&out.stderr)
        );
        String::from_utf8_lossy(&out.stdout).into_owned()
    };

    run(&["new", doc.to_str().unwrap(), "--label", "pad"]);
    run(&["add", doc.to_str().unwrap(), "sketch"]);
    std::fs::write(dir.join("ring.xml"), fixtures::ring_sketch_xml()).unwrap();
    run(&[
        "sketch-import",
        doc.to_str().unwrap(),
        "Sketch",
        dir.join("ring.xml").to_str().unwrap(),
    ]);
    run(&[
        "pad",
        doc.to_str().unwrap(),
        "--sketch",
        "Sketch",
        "--length",
        "8",
    ]);
    let pad_volume = volume_of(&run(&["stats", doc.to_str().unwrap()]));
    let exact = (std::f64::consts::PI * (10.0_f64 * 10.0 - 4.0 * 4.0)) * 8.0;
    // The Pad itself tessellates its circular profile under the kernel's
    // sagitta discipline (an inscribed polygon), so its own volume sits a
    // hair under the analytic one — bounded by the same per-wall deficit
    // used below (both walls, one stage, pad-height 8):
    let deficit = |r: f64, d: f64| {
        let step = 2.0 * (1.0 - d / r).acos();
        std::f64::consts::PI / 12.0 * r * step * step * 8.0
    };
    let pad_bound = deficit(10.0, 0.2) + deficit(4.0, 0.2);
    assert!(
        (pad_volume - exact).abs() <= pad_bound * 2.0,
        "pad volume {pad_volume} vs analytic {exact} (bound {pad_bound})"
    );

    // Export → re-import → volume round-trip within the deflection-
    // derived tolerance (export deflection 0.2, import 0.2).
    run(&[
        "export",
        "step",
        doc.to_str().unwrap(),
        step_out.to_str().unwrap(),
    ]);
    run(&[
        "import-step",
        doc2.to_str().unwrap(),
        step_out.to_str().unwrap(),
        "--deflection",
        "0.2",
    ]);
    let round_volume = volume_of(&run(&["stats", doc2.to_str().unwrap()]));
    // Both tessellations are inscribed under their deflection; the
    // round-trip error is bounded by the sum of the per-wall sagitta
    // deficits at each stage: (π/12)·r·step²·h per wall per stage.
    let deficit = |r: f64, d: f64| {
        let step = 2.0 * (1.0 - d / r).acos();
        std::f64::consts::PI / 12.0 * r * step * step * 8.0
    };
    let bound = deficit(10.0, 0.2) + deficit(4.0, 0.2) + deficit(10.0, 0.2) + deficit(4.0, 0.2);
    assert!(
        (round_volume - pad_volume).abs() <= bound * 2.0 + 1e-6,
        "round-trip volume {round_volume} vs pad {pad_volume}: bound {bound}"
    );
    assert!(
        (round_volume - exact).abs() / exact < 0.02,
        "round-trip volume {round_volume} vs analytic {exact} (>2% off)"
    );
    let _ = std::fs::remove_dir_all(&dir);
}

#[test]
fn exported_file_carries_the_faceted_marker_in_metadata() {
    let dir = std::env::temp_dir().join(format!("fc-step-marker-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let doc = dir.join("m.fcstd");
    let step_out = dir.join("m.step");

    let cli = cli_path();
    let run = |args: &[&str]| {
        let out = Command::new(&cli).args(args).output().unwrap();
        assert!(
            out.status.success(),
            "freecad-rs {:?} failed: {}",
            args,
            String::from_utf8_lossy(&out.stderr)
        );
    };
    run(&["new", doc.to_str().unwrap(), "--label", "m"]);
    run(&[
        "add",
        doc.to_str().unwrap(),
        "box",
        "--length",
        "5",
        "--width",
        "5",
        "--height",
        "5",
    ]);
    run(&[
        "export",
        "step",
        doc.to_str().unwrap(),
        step_out.to_str().unwrap(),
    ]);

    // The marker is asserted IN THE FILE (product name), not merely in
    // docs — ADR-0002 decision 3.
    let text = std::fs::read_to_string(&step_out).unwrap();
    assert!(
        text.contains(fc_step::FACETED_MARKER),
        "exported STEP lacks the faceted marker in its product name"
    );
    // And it is a legal Part 21 file that parses back.
    let set = fc_step::parse::EntitySet::parse(&text).unwrap();
    assert_eq!(set.all("MANIFOLD_SOLID_BREP").len(), 1);
    let _ = std::fs::remove_dir_all(&dir);
}

#[test]
fn honest_errors_on_unsupported_content() {
    // No solid at all → an error, not a silent drop.
    let bad = "ISO-10303-21;\nHEADER;\nFILE_DESCRIPTION(('x'),'2;1');\n\
FILE_NAME('x.step','',('x'),('x'),'','','');\n\
FILE_SCHEMA(('AUTOMOTIVE_DESIGN {{ 1 0 10303 214 1 1 1 1 }}'));\nENDSEC;\nDATA;\n\
#1=TOROIDAL_SURFACE('',#2,10.,2.);\n#2=AXIS2_PLACEMENT_3D('',#3,#4,#5);\n\
#3=CARTESIAN_POINT('',(0.,0.,0.));\n#4=DIRECTION('',(0.,0.,1.));\n#5=DIRECTION('',(1.,0.,0.));\n\
ENDSEC;\nEND-ISO-10303-21;\n";
    let set = fc_step::parse::EntitySet::parse(bad).unwrap();
    let err = fc_step::import::import_solids(&set, 0.1).unwrap_err();
    assert!(err.contains("no MANIFOLD_SOLID_BREP"), "got: {err}");

    // Not STEP at all → a parse error with an honest message.
    let err = fc_step::parse::EntitySet::parse("hello world").unwrap_err();
    assert!(err.contains("cannot parse STEP"), "got: {err}");
}

/// Locate the CLI binary built by the workspace (test profile).
fn cli_path() -> PathBuf {
    let exe = if cfg!(windows) {
        "freecad-rs.exe"
    } else {
        "freecad-rs"
    };
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../target/debug")
        .join(exe)
}

/// FreeCAD 1.0 writes `Part::Sphere` as ONE spherical face whose only
/// bound is a VERTEX_LOOP at a pole — the whole sphere, no edge
/// geometry. The reader must tessellate the surface itself
/// (lat/long bands under the sagitta rule), and the mesh must be
/// closed with a positive volume converging to the exact sphere.
#[test]
fn freecad_whole_sphere_vertex_loop_imports() {
    // Verbatim structure of FreeCAD 1.0's export of Part::Sphere
    // (radius 5): one MANIFOLD_SOLID_BREP, one face, VERTEX_LOOP.
    let step = concat!(
        "ISO-10303-21;\n",
        "HEADER;\n",
        "FILE_DESCRIPTION(('FreeCAD 1.0 sphere'),'2;1');\n",
        "ENDSEC;\n",
        "DATA;\n",
        "#2 = APPLICATION_PROTOCOL_DEFINITION('international standard','automotive_design',2000,#1);\n",
        "#11 = AXIS2_PLACEMENT_3D('',#8,#9,#10);\n",
        "#8 = CARTESIAN_POINT('',(0.,0.,0.));\n",
        "#9 = DIRECTION('',(0.,0.,1.));\n",
        "#10 = DIRECTION('',(1.,0.,0.));\n",
        "#14 = PRODUCT_DEFINITION_SHAPE('','',#15);\n",
        "#15 = PRODUCT_DEFINITION('design','',#16,#18);\n",
        "#16 = PRODUCT_DEFINITION_FORMATION('','',#17);\n",
        "#17 = PRODUCT('Ball','Ball','',(#19));\n",
        "#18 = PRODUCT_DEFINITION_CONTEXT('part definition',#2,'design');\n",
        "#19 = PRODUCT_CONTEXT('',#2,'mechanical');\n",
        "#20 = MANIFOLD_SOLID_BREP('',#21);\n",
        "#21 = CLOSED_SHELL('',(#22));\n",
        "#22 = ADVANCED_FACE('',(#23),#26,.T.);\n",
        "#23 = FACE_BOUND('',#24,.T.);\n",
        "#24 = VERTEX_LOOP('',#25);\n",
        "#25 = VERTEX_POINT('',#27);\n",
        "#27 = CARTESIAN_POINT('',(3.061616997868383E-16,0.,-5.));\n",
        "#26 = SPHERICAL_SURFACE('',#28,5.);\n",
        "#28 = AXIS2_PLACEMENT_3D('',#8,#9,#10);\n",
        "ENDSEC;\n",
        "END-ISO-10303-21;\n"
    );
    let dir = std::env::temp_dir().join("fc-step-freecad-sphere-test");
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("freecad-sphere.step");
    std::fs::write(&path, step).unwrap();
    let text = std::fs::read_to_string(&path).unwrap();
    let set = fc_step::parse::EntitySet::parse(&text).unwrap();
    let solids = fc_step::import::import_solids(&set, 0.05).unwrap();
    assert_eq!(solids.len(), 1, "one solid");
    let (_, mesh) = &solids[0];
    assert!(mesh.triangle_count() > 100, "a tessellated sphere");
    // Closed and consistently oriented.
    assert!(
        fc_part::boolean::mesh_is_closed(mesh),
        "whole-sphere import is watertight"
    );
    assert!(
        fc_part::boolean::mesh_is_consistently_oriented(mesh),
        "whole-sphere import is consistently oriented"
    );
    // Converging to the exact sphere: the sagitta bound is 0.05 mm
    // on r = 5, so the volume lands within a few percent and the
    // surface points sit ON the radius.
    let exact = 4.0 / 3.0 * std::f64::consts::PI * 125.0;
    let got = mesh.volume();
    assert!(
        (got - exact).abs() / exact < 0.06,
        "volume {got} within the deflection contract of {exact}"
    );
    for v in &mesh.vertices {
        let r = v.length();
        assert!((r - 5.0).abs() < 1e-9, "every vertex on the sphere (r={r})");
    }
}

/// FreeCAD 1.0 writes `Part::Cone` (radius 3 → 0, height 10) and
/// `Part::Torus` (major 5, minor 1) as single curved faces — the
/// cone over a CONICAL_SURFACE whose placement axis points DOWN
/// (OCCT parametrizes v from the apex), the torus over a
/// TOROIDAL_SURFACE whose seam loop carries both full circles. The
/// reader tessellates both and the shell-level orientation makes
/// the solids positive.
#[test]
fn freecad_cone_and_torus_import() {
    let step = concat!(
        "ISO-10303-21;\n",
        "HEADER;\n",
        "FILE_DESCRIPTION(('FreeCAD 1.0 cone+torus'),'2;1');\n",
        "ENDSEC;\n",
        "DATA;\n",
        "#2 = APPLICATION_PROTOCOL_DEFINITION('international standard','automotive_design',2000,#1);\n",
        "#11 = AXIS2_PLACEMENT_3D('',#8,#9,#10);\n",
        "#8 = CARTESIAN_POINT('',(0.,0.,0.));\n",
        "#9 = DIRECTION('',(0.,0.,1.));\n",
        "#10 = DIRECTION('',(1.,0.,0.));\n",
        "#24 = ( LENGTH_UNIT() NAMED_UNIT(*) SI_UNIT(.MILLI.,.METRE.) );\n",
        "#14 = PRODUCT_DEFINITION_SHAPE('','',#15);\n",
        "#15 = PRODUCT_DEFINITION('design','',#16,#18);\n",
        "#16 = PRODUCT_DEFINITION_FORMATION('','',#17);\n",
        "#18 = PRODUCT_DEFINITION_CONTEXT('part definition',#2,'design');\n",
        // ---- the cone, verbatim FreeCAD structure: lateral face over
        // CONICAL_SURFACE (axis pointing DOWN — v from the apex),
        // loop = seam line + base circle + seam back
        "#80 = PRODUCT('Cone','Cone','',(#81));\n",
        "#81 = PRODUCT_CONTEXT('',#2,'mechanical');\n",
        "#82 = MANIFOLD_SOLID_BREP('',#83);\n",
        "#83 = CLOSED_SHELL('',(#84,#108));\n",
        "#84 = ADVANCED_FACE('',(#85),#95,.T.);\n",
        "#85 = FACE_BOUND('',#86,.T.);\n",
        "#86 = EDGE_LOOP('',(#87,#93,#94));\n",
        "#87 = ORIENTED_EDGE('',*,*,#88,.F.);\n",
        "#88 = EDGE_CURVE('',#89,#91,#90,.T.);\n",
        "#89 = VERTEX_POINT('',#100);\n",
        "#100 = CARTESIAN_POINT('',(3.,0.,0.));\n",
        "#91 = VERTEX_POINT('',#92);\n",
        "#92 = CARTESIAN_POINT('',(0.,0.,10.));\n",
        "#90 = LINE('',#101,#102);\n",
        "#101 = CARTESIAN_POINT('',(3.,0.,0.));\n",
        "#102 = VECTOR('',#103,1.);\n",
        "#103 = DIRECTION('',(-0.287347885566,0.,0.957826285221));\n",
        "#93 = ORIENTED_EDGE('',*,*,#104,.T.);\n",
        "#104 = EDGE_CURVE('',#89,#89,#105,.T.);\n",
        "#105 = CIRCLE('',#106,3.);\n",
        "#106 = AXIS2_PLACEMENT_3D('',#8,#9,#10);\n",
        "#94 = ORIENTED_EDGE('',*,*,#88,.T.);\n",
        "#95 = CONICAL_SURFACE('',#96,3.,0.291456794478);\n",
        "#96 = AXIS2_PLACEMENT_3D('',#8,#97,#10);\n",
        "#97 = DIRECTION('',(0.,0.,-1.));\n",
        // the base disk: the same base circle, as a planar face
        "#108 = ADVANCED_FACE('',(#109),#113,.F.);\n",
        "#109 = FACE_BOUND('',#110,.T.);\n",
        "#110 = EDGE_LOOP('',(#111));\n",
        "#111 = ORIENTED_EDGE('',*,*,#104,.F.);\n",
        "#113 = PLANE('',#114);\n",
        "#114 = AXIS2_PLACEMENT_3D('',#8,#9,#10);\n",
        // ---- the torus: one toroidal face, the seam loop with both circles
        "#40 = PRODUCT_DEFINITION_SHAPE('','',#41);\n",
        "#41 = PRODUCT_DEFINITION('design','',#42,#44);\n",
        "#42 = PRODUCT_DEFINITION_FORMATION('','',#43);\n",
        "#43 = PRODUCT('Ring','Ring','',(#45));\n",
        "#44 = PRODUCT_DEFINITION_CONTEXT('part definition',#2,'design');\n",
        "#45 = PRODUCT_CONTEXT('',#2,'mechanical');\n",
        "#46 = MANIFOLD_SOLID_BREP('',#47);\n",
        "#47 = CLOSED_SHELL('',(#48));\n",
        "#48 = ADVANCED_FACE('',(#49),#68,.T.);\n",
        "#49 = FACE_BOUND('',#50,.F.);\n",
        "#50 = EDGE_LOOP('',(#51,#60,#66,#67));\n",
        "#51 = ORIENTED_EDGE('',*,*,#52,.T.);\n",
        "#52 = EDGE_CURVE('',#53,#53,#55,.T.);\n",
        "#53 = VERTEX_POINT('',#54);\n",
        "#54 = CARTESIAN_POINT('',(4.,0.,-1.224646799147E-16));\n",
        "#55 = CIRCLE('',#56,4.);\n",
        "#56 = AXIS2_PLACEMENT_3D('',#57,#58,#59);\n",
        "#57 = CARTESIAN_POINT('',(0.,0.,-1.224646799147E-16));\n",
        "#58 = DIRECTION('',(0.,0.,1.));\n",
        "#59 = DIRECTION('',(1.,0.,0.));\n",
        "#60 = ORIENTED_EDGE('',*,*,#61,.F.);\n",
        "#61 = EDGE_CURVE('',#53,#53,#62,.T.);\n",
        "#62 = CIRCLE('',#63,1.);\n",
        "#63 = AXIS2_PLACEMENT_3D('',#64,#65,#10);\n",
        "#64 = CARTESIAN_POINT('',(5.,0.,0.));\n",
        "#65 = DIRECTION('',(0.,1.,0.));\n",
        "#66 = ORIENTED_EDGE('',*,*,#52,.F.);\n",
        "#67 = ORIENTED_EDGE('',*,*,#61,.T.);\n",
        "#68 = TOROIDAL_SURFACE('',#11,5.,1.);\n",
        "ENDSEC;\n",
        "END-ISO-10303-21;\n"
    );
    let dir = std::env::temp_dir().join("fc-step-freecad-cone-torus-test");
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("freecad-cone-torus.step");
    std::fs::write(&path, step).unwrap();
    let set = fc_step::parse::EntitySet::parse(step).unwrap();
    let solids = fc_step::import::import_solids(&set, 0.05).unwrap();
    assert_eq!(solids.len(), 2, "two solids");
    // Ascending entity id order: the torus's brep (#46) precedes the
    // cone's (#82).
    let (torus, cone) = (&solids[0].1, &solids[1].1);
    for (name, m) in [("cone", cone), ("torus", torus)] {
        assert!(fc_part::boolean::mesh_is_closed(m), "{name}: watertight");
        assert!(
            fc_part::boolean::mesh_is_consistently_oriented(m),
            "{name}: consistently oriented"
        );
    }
    // The cone: the apex VERTEX_LOOP makes it a whole cone; positive
    // volume (OCCT's cone placement axis points down — the shell
    // orienter, not the per-face flag, settles the sign).
    let cone_exact = std::f64::consts::PI * 9.0 * 10.0 / 3.0;
    let got = cone.volume();
    assert!(got > 0.0, "cone volume positive (got {got})");
    assert!(
        (got - cone_exact).abs() / cone_exact < 0.05,
        "cone volume {got} within the deflection contract of {cone_exact}"
    );
    // The torus: whole-torus grid, positive volume.
    let torus_exact = 2.0 * std::f64::consts::PI * std::f64::consts::PI * 5.0;
    let got = torus.volume();
    assert!(got > 0.0, "torus volume positive (got {got})");
    assert!(
        (got - torus_exact).abs() / torus_exact < 0.12,
        "torus volume {got} within the deflection contract of {torus_exact}"
    );
}
